// ========================================
// SOCKET.IO
// ========================================

const socket = io(
    window.location.origin
);

// ========================================
// ESCUCHAR EVENTOS
// ========================================

socket.on(
    'connect',
    () => {

        console.log(
            'Socket conectado'
        );
    }
);

socket.on(
    'disconnect',
    () => {

        console.log(
            'Socket desconectado'
        );
    }
);

// ========================================
// EVENTOS EN TIEMPO REAL
// ========================================

socket.on(
    'nuevo_consumo',
    (evento) => {

        console.log(
            'Evento realtime:',
            evento
        );

        if (
            evento.tipo === 'consumo'
        ) {

            actualizarRealtimeConsumo(
                evento.data
            );
        }

        if (
            evento.tipo === 'alerta'
        ) {

            actualizarRealtimeAlerta(
                evento.data
            );
        }
    }
);

// ========================================
// CONSUMO REALTIME
// ========================================

function actualizarRealtimeConsumo(
    data
) {

    // =========================
    // KPI TOTAL
    // =========================

    const totalElement =
        document.getElementById(
            'kpiConsumo'
        );

    if (totalElement) {

        const texto =
            totalElement.textContent
                .replace('kWh', '')
                .trim();

        const actual =
            parseFloat(texto) || 0;

        const nuevo =
            actual + Number(data.consumo);

        totalElement.innerHTML =
            `${nuevo.toFixed(2)} <span>kWh</span>`;
    }

    // =========================
    // GRAFICO PRINCIPAL
    // =========================

    if (
        state.charts.main
    ) {

        const now =
            new Date();

        const label =
            now.toLocaleTimeString(
                'es-ES',
                {
                    hour: '2-digit',
                    minute: '2-digit',
                    second: '2-digit'
                }
            );

        state.charts.main
            .data.labels.push(label);

        state.charts.main
            .data.datasets[0]
            .data.push(
                Number(data.consumo)
            );

        if (
            state.charts.main
                .data.labels.length > 15
        ) {

            state.charts.main
                .data.labels.shift();

            state.charts.main
                .data.datasets[0]
                .data.shift();
        }

        state.charts.main.update(
            'none'
        );
    }

    // =========================
    // TOP DEVICES
    // =========================

    agregarRealtimeDevice(
        data
    );
}

// ========================================
// DISPOSITIVOS ACTUALIZADO (REALTIME)
// ========================================

socket.on(
    'dispositivo_actualizado',
    (data) => {

        console.log(
            'Dispositivo actualizado:',
            data
        );

        actualizarDispositivoRealtime(data);
    }
);

// ========================================
// ALERTA REALTIME
// ========================================

function actualizarRealtimeAlerta(
    alerta
) {

    // =========================
    // KPI ALERTAS
    // =========================

    const alertElement =
        document.getElementById(
            'kpiAlertas'
        );

    if (alertElement) {

        const actual =
            parseInt(
                alertElement.textContent
            ) || 0;

        alertElement.textContent =
            actual + 1;
    }

    // =========================
    // TOAST
    // =========================

    showToast(

        'Alerta crítica',

        `${alerta.dispositivo_id}
         • ${alerta.severidad}`
    );

    // =========================
    // LISTA ALERTAS
    // =========================

    agregarRealtimeAlerta(
        alerta
    );
}

// ========================================
// AGREGAR ALERTA DOM
// ========================================

function agregarRealtimeAlerta(
    alerta
) {

    const container =
        document.getElementById(
            'alertsGrid'
        );

    if (!container) return;

    const severity =
        (
            alerta.severidad || 'MEDIA'
        ).toUpperCase();

    const badge =
        buildSeverityBadge(
            severity
        );

    const card = document.createElement(
        'div'
    );

    card.className =
        'alert-card realtime-new';

    card.innerHTML = `

        <div class="alert-card-header">

            <h5>
                ${alerta.dispositivo_id}
            </h5>

            ${badge}

        </div>

        <div class="alert-card-body">

            <p>
                <strong>Zona:</strong>
                ${alerta.zona}
            </p>

            <p>
                <strong>Consumo:</strong>
                ${Number(
                    alerta.consumo
                ).toFixed(2)} kWh
            </p>

            <p>
                <strong>Recomendación:</strong>
                ${alerta.recomendacion}
            </p>

            <p class="kpi-note">
                ${formatTimestamp(
                    alerta.timestamp
                )}
            </p>

        </div>
    `;

    container.prepend(card);

    // limitar cantidad

    while (
        container.children.length > 15
    ) {

        container.removeChild(
            container.lastChild
        );
    }
}

// ========================================
// AGREGAR DEVICE DOM
// ========================================

function agregarRealtimeDevice(
    data
) {

    const container =
        document.getElementById(
            'topDevicesList'
        );

    if (!container) return;

    const item =
        document.createElement(
            'div'
        );

    item.className =
        'device-card realtime-new';

    item.innerHTML = `

        <div class="device-card-header">

            <h5>
                ${data.dispositivo_id}
            </h5>

            <span class="device-zone">
                ${data.zona}
            </span>

        </div>

        <div class="device-card-body">

            <p>
                ${Number(
                    data.consumo
                ).toFixed(2)} kWh
            </p>

            <small>
                ${formatTimestamp(
                    data.timestamp
                )}
            </small>

        </div>
    `;

    container.prepend(item);

    while (
        container.children.length > 10
    ) {

        container.removeChild(
            container.lastChild
        );
    }
}